              denied(h,cast(h,source,friend),"own support is not enemy");denied(h,cast(h,source,ally),"allied support is not enemy");denied(h,cast(h,source,wild),"actual wild non-Unit is not a grip target");denied(h,cast(h,source,other),"actual Player is not a grip target");require(h,cast(h,source,far),SkillResult.RANGE,"outside exact range6");victim.setInvisible(true);require(h,cast(h,source,victim),SkillResult.HIDDEN,"actual invisible enemy");victim.setInvisible(false);require(h,java.util.concurrent.CompletableFuture.supplyAsync(()->decoded.execute(owner)).join(),SkillResult.INVALID_REQUEST,"off-thread service stays inert");
              h.assertTrue(cd(source)==0&&source.rts().skills().revision()==revision&&!ShadowHandGrip.active(source)&&!ShadowHandGrip.hasRoot(victim),"all invalid requests leave paid and short authority unchanged");h.assertTrue(source.getAbilities().get().equals(List.of(UnitSkillAbility.SHADOW_HAND_GRIP)),"exact approved active ability, not original reserved special interface");at[0]=h.getLevel().getGameTime();require(h,decoded.execute(owner),SkillResult.SUCCESS,"real exact6-range enemy support reservation");h.assertTrue(cd(source)==440&&ShadowHandGrip.remainingWindupTicks(source)==10&&!ShadowHandGrip.hasRoot(victim)&&ShadowHandGrip.remainingRecontrolTicks(victim)==0,"reservation pays440 and starts10, never roots or protects early");require(h,decoded.execute(owner),SkillResult.REPLAY,"old packet cannot reserve twice");require(h,cast(h,source,victim),SkillResult.COOLDOWN,"fresh paid request remains cooling");bank(h);
