    /** Diagnostic only: fixed samples before the unchanged original admission; raw reads never create paths/chunks. */
    private static void gripAdmissionRaw(GameTestHelper h,List<Mob> actors,Vec3[] before,long start,Set<Long> sampled){
        long elapsed=h.getLevel().getGameTime()-start;if(!Set.of(0L,1L,2L,4L,10L,20L,60L,100L,150L,180L,190L).contains(elapsed)||!sampled.add(elapsed))return;
        for(int i=0;i<actors.size();i++){var a=actors.get(i);var path=a.getNavigation().getPath();var end=path==null?null:path.getEndNode();System.out.println("SHADOW_HAND_GRIP_PRECAST_RAW elapsed="+elapsed+" gameTime="+h.getLevel().getGameTime()+" lane="+i+" id="+a.getId()+" uuid="+a.getUUID()+" tick="+a.tickCount+" pos="+a.position()+" velocity="+a.getDeltaMovement()+" fromInitial="+a.position().subtract(before[i])+" horizontalFromInitialSq="+a.position().subtract(before[i]).horizontalDistanceSqr()+" horizontalVelocitySq="+a.getDeltaMovement().horizontalDistanceSqr()+" noAI="+a.isNoAi()+" noGravity="+a.isNoGravity()+" pending="+UnitServerEvents.hasPendingImmediateAction(a.getId())+" command="+((Unit)a).getMoveGoal().getMoveTarget()+" pathPresent="+(path!=null)+" pathTarget="+(path==null?null:path.getTarget())+" pathEnd="+(end==null?null:end.asBlockPos())+" navDone="+a.getNavigation().isDone()+" control="+a.getMoveControl().getClass().getName()+" operation="+a.getMoveControl().operation+" onGround="+a.onGround()+" verticalCollision="+a.verticalCollision+" exactID="+(h.getLevel().getEntity(a.getId())==a)+" exactUUID="+(h.getLevel().getEntity(a.getUUID())==a));}
    }
    private record GripMovementRead(long time,int lane,Vec3 position,Vec3 velocity,BlockPos command,boolean noAI,boolean ground,boolean horizontalCollision,boolean water,boolean lava,boolean stone,float health,int root,Object operation){}
    private static final class GripMovementProbe{
        final GameTestHelper h;final List<Mob> actors;final List<GripMovementRead> reads=new ArrayList<>();RuntimeException failure;GripMovementProbe(GameTestHelper h,List<Mob> actors){this.h=h;this.actors=actors;}
        GripMovementRead at(int lane,long time){return reads.stream().filter(r->r.lane==lane&&r.time==time).findFirst().orElse(null);}
        @SubscribeEvent(priority=EventPriority.LOWEST) public void end(TickEvent.LevelTickEvent e){if(e.phase!=TickEvent.Phase.END||e.level!=h.getLevel()||failure!=null)return;try{for(int i=0;i<actors.size();i++){var a=actors.get(i);BlockPos floor=BlockPos.containing(a.getX(),a.getBoundingBox().minY-.01,a.getZ());var chunk=h.getLevel().getChunkSource().getChunkNow(floor.getX()>>4,floor.getZ()>>4);var r=new GripMovementRead(e.level.getGameTime(),i,a.position(),a.getDeltaMovement(),((Unit)a).getMoveGoal().getMoveTarget(),a.isNoAi(),a.onGround(),a.horizontalCollision,a.isInWater(),a.isInLava(),chunk!=null&&chunk.getBlockState(floor).is(Blocks.STONE),a.getHealth(),ShadowHandGrip.remainingRootTicks(a),a.getMoveControl().operation);reads.add(r);if(r.root>0)System.out.println("SHADOW_HAND_GRIP_REAL_MOVEMENT "+r);}}catch(RuntimeException error){failure=error;}}
    }

