    private static final class GripPassiveCallbacks{
        final GameTestHelper h;final List<ShadowHandUnit> sources;final List<GoldenFoxUnit> targets;final boolean[] fired=new boolean[6];boolean armed,sameAccepted,otherAccepted,zeroAccepted;double sameLoss,otherLoss,zeroLoss;RuntimeException failure;
        GripPassiveCallbacks(GameTestHelper h,List<ShadowHandUnit> sources,List<GoldenFoxUnit> targets){this.h=h;this.sources=sources;this.targets=targets;}
        int lane(LivingEntity target,DamageSource damage){int i=targets.indexOf(target);return armed&&failure==null&&i>=0&&!fired[i]&&damage.getEntity()==sources.get(i)&&damage.getDirectEntity()==sources.get(i)?i:-1;}
        @SubscribeEvent(priority=EventPriority.HIGHEST,receiveCanceled=true) public void hurt(LivingHurtEvent e){int i=lane(e.getEntity(),e.getSource());if(i<2||i>4)return;fired[i]=true;try{float last=((Number)rawField(e.getEntity(),"lastHurt")).floatValue();int iframe=e.getEntity().invulnerableTime;float delta=i==2?10:2,input=iframe>10?last+delta:delta;float hp=e.getEntity().getHealth();boolean accepted=e.getEntity().hurt(i==2?e.getSource():e.getEntity().damageSources().generic(),input);double loss=hp-e.getEntity().getHealth();if(i==2){sameAccepted=accepted;sameLoss=loss;}else if(i==3){otherAccepted=accepted;otherLoss=loss;}else{zeroAccepted=accepted;zeroLoss=loss;e.setAmount(0);}System.out.println("SHADOW_HAND_GRIP_CALLBACK_RAW lane="+i+" iframe="+iframe+" lastHurt="+last+" input="+input+" accepted="+accepted+" actualInnerHP="+loss);}catch(RuntimeException error){failure=error;}}
        @SubscribeEvent(priority=EventPriority.HIGHEST,receiveCanceled=true) public void damage(LivingDamageEvent e){int i=lane(e.getEntity(),e.getSource());if(i!=0&&i!=1&&i!=5)return;fired[i]=true;try{if(i==0)e.getEntity().removeEffect(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN);else if(i==1)e.getEntity().addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN,100,0));else{var target=targets.get(i);String owner=target.getOwnerName();target.setOwnerName(owner+"Temporary");target.setOwnerName(owner);}}catch(RuntimeException error){failure=error;}}
    }

