            if(tick>=12&&tick<=28){var read=probe.at(h.getLevel().getGameTime()-1);h.assertTrue(read!=null&&read.root>0&&!read.rootNoAI&&!read.controlNoAI,"completed natural physical interval under actual root, not NoAI freeze");close(h,read.rootPosition.x-read.controlPosition.x,-10,"root preserves native external horizontal knockback trajectory");close(h,read.rootPosition.y,read.controlPosition.y,"root preserves actual gravitational descent");close(h,read.rootPosition.z,read.controlPosition.z,"matched no new autonomous lateral input");close(h,read.rootVelocity.x,read.controlVelocity.x,"native knockback/friction x unchanged");close(h,read.rootVelocity.y,read.controlVelocity.y,"native gravity/collision y unchanged");close(h,read.rootVelocity.z,read.controlVelocity.z,"native friction z unchanged");close(h,read.rootHp,read.controlHp,"same native physical/fall health outcome");}
            if(tick==14)order(h,jumpRoot,UnitAction.MOVE,null,destination);
            if(tick==17){h.assertTrue(ShadowHandGrip.hasRoot(jumpRoot)&&!UnitServerEvents.hasPendingImmediateAction(jumpRoot.getId())&&jumpRoot.getMoveGoal().getMoveTarget()!=null,"real new MOVE dispatch updates current command during root");accepted[0]=jumpRoot.getMoveGoal().getMoveTarget();}
            if(tick==29)h.assertTrue(ShadowHandGrip.remainingRootTicks(jumpRoot)==1&&Objects.equals(jumpRoot.getMoveGoal().getMoveTarget(),accepted[0]),"root retains accepted newer order rather than an old-state restoration slot");
